CREATE TABLE IF NOT EXISTS `stl_items` (
  `stl_item_id` int NOT NULL AUTO_INCREMENT,
  `stl_item_status` enum('черновик','в работе','архив','удалено','') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'черновик',
  `stl_item_code_basis` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'Основание',
  `stl_item_code` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `stl_item_favorite` tinyint(1) DEFAULT '0',
  `stl_item_public` tinyint(1) NOT NULL DEFAULT '0',
  `stl_item_img` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `stl_item_update` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `user_id` int UNSIGNED DEFAULT NULL,
  `guest_id` int DEFAULT NULL,
  `answer_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`stl_item_id`),
  KEY `user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7091 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

