INSERT INTO `stl_items` (`stl_item_id`, `stl_item_status`, `stl_item_code_basis`, `stl_item_code`, `stl_item_favorite`, `stl_item_public`, `stl_item_img`, `stl_item_update`, `user_id`, `guest_id`, `answer_id`, `created_at`) VALUES
(7077, 'в работе', '3D модель прижимного фланца для герметичного соединения труб с помощью болтов и прокладок.', '/*\n   ===================================================================\n   Параметрическая 3D-модель прижимного фланца с пазом под уплотнение\n   ===================================================================\n   Назначение: Герметичное фланцевое соединение трубных систем\n   Особенности: \n     - Коническая ступица (юбка) для снятия напряжений\n     - Канавка под резиновое кольцо круглого сечения (O-Ring)\n     - Посадочное гнездо под трубу с упорным бортиком\n     - Цековка/углубления под шляпки болтов или гайки\n     - Фаски на кромках для снижения концентрации напряжений\n*/\n\n// --- ГЛОБАЛЬНЫЕ НАСТРОЙКИ СЕТКИ ---\n$fn = 42; // Ограничение плотности сетки ($fn < 50) для быстрой генерации\n\n// --- ОСНОВНЫЕ ПАРАМЕТРЫ ТРУБЫ ---\npipe_inner_d      = 32.0;  // Внутренний диаметр трубы (проходной канал), мм\npipe_outer_d      = 40.0;  // Внешний диаметр соединяемой трубы, мм\npipe_socket_depth = 18.0;  // Глубина посадки трубы в муфту фланца, мм\npipe_clearance    = 0.3;   // Зазор на посадку трубы под склейку/пайку/сварку, мм\n\n// --- ПАРАМЕТРЫ ТЕЛА ФЛАНЦА ---\nflange_outer_d    = 110.0; // Внешний диаметр прижимного диска, мм\nflange_thickness  = 12.0;  // Толщина прижимного диска, мм\nhub_height        = 22.0;  // Общая высота фланца вместе со ступицей, мм\nhub_top_wall      = 4.5;   // Толщина стенки на вершине муфты, мм\n\n// --- ПАРАМЕТРЫ БОЛТОВОГО КРЕПЛЕНИЯ ---\nbolt_count        = 4;     // Количество крепежных отверстий (равномерно по кругу)\nbolt_pcd          = 82.0;  // Диаметр центров крепежных отверстий (PCD), мм\nbolt_hole_d       = 9.0;   // Диаметр отверстия под болт (стандарт M8), мм\nbolt_recess_d     = 16.0;  // Диаметр цековки под головку/шайбу болта, мм\nbolt_recess_depth = 3.0;   // Глубина цековки под болт, мм\n\n// --- ПАРАМЕТРЫ УПЛОТНИТЕЛЬНОЙ КАНАВКИ (O-RING) ---\noring_center_d    = 54.0;  // Средний диаметр канавки уплотнения, мм\noring_groove_w    = 4.2;   // Ширина канавки под резиновое кольцо, мм\noring_groove_depth= 2.6;   // Глубина канавки под кольцо (с учетом сжатия), мм\n\n// Вспомогательная константа для чистого вычитания без мерцания граней\neps = 0.05; \n\n// ===================================================================\n// ОСНОВНОЙ МОДУЛЬ СБОРКИ ФЛАНЦА\n// ===================================================================\nmodule compression_flange() {\n    // Расчет внешнего диаметра муфты у вершины\n    hub_top_od = pipe_outer_d + (pipe_clearance * 2) + (hub_top_wall * 2);\n    // Диаметр основания конуса ступицы\n    hub_base_od = hub_top_od + 10.0;\n\n    difference() {\n        // --- 1. ТЕЛО ФЛАНЦА (ПОЛОЖИТЕЛЬНЫЙ ОБЪЕМ) ---\n        union() {\n            // Основной прижимной диск\n            cylinder(d = flange_outer_d, h = flange_thickness);\n            \n            // Коническая ступица (юбка усиления)\n            translate([0, 0, flange_thickness - eps])\n                cylinder(\n                    d1 = hub_base_od, \n                    d2 = hub_top_od, \n                    h = hub_height - flange_thickness + eps\n                );\n        }\n\n        // --- 2. ВЫЧИТАЕМЫЕ ЭЛЕМЕНТЫ (ОТРИЦАТЕЛЬНЫЙ ОБЪЕМ) ---\n        \n        // Центральный проходной канал\n        translate([0, 0, -eps])\n            cylinder(d = pipe_inner_d, h = hub_height + 2 * eps);\n\n        // Посадочное гнездо под трубу со стопорным буртом\n        translate([0, 0, hub_height - pipe_socket_depth])\n            cylinder(\n                d = pipe_outer_d + (pipe_clearance * 2), \n                h = pipe_socket_depth + eps\n            );\n\n        // Фаска для удобства захода трубы в муфту\n        translate([0, 0, hub_height - 1.5 + eps])\n            cylinder(\n                d1 = pipe_outer_d + (pipe_clearance * 2), \n                d2 = pipe_outer_d + (pipe_clearance * 2) + 3.0, \n                h = 1.5 + eps\n            );\n\n        // Кольцевой паз под уплотнительную прокладку (на зеркале фланца)\n        translate([0, 0, -eps])\n            difference() {\n                cylinder(d = oring_center_d + oring_groove_w, h = oring_groove_depth + eps);\n                translate([0, 0, -eps])\n                    cylinder(d = oring_center_d - oring_groove_w, h = oring_groove_depth + 3 * eps);\n            }\n\n        // Входная фаска центрального канала на рабочей плоскости\n        translate([0, 0, -eps])\n            cylinder(d1 = pipe_inner_d + 3.0, d2 = pipe_inner_d, h = 1.5);\n\n        // Сетка крепежных отверстий с цековками\n        for (i = [0 : bolt_count - 1]) {\n            rotate([0, 0, i * (360 / bolt_count)]) {\n                translate([bolt_pcd / 2, 0, 0]) {\n                    // Сквозное отверстие под болт\n                    translate([0, 0, -eps])\n                        cylinder(d = bolt_hole_d, h = flange_thickness + 2 * eps);\n                    \n                    // Цековка (углубление) под головку/шайбу с тыльной стороны\n                    translate([0, 0, flange_thickness - bolt_recess_depth])\n                        cylinder(d = bolt_recess_d, h = bolt_recess_depth + eps);\n                }\n            }\n        }\n\n        // Внешняя фаска на прижимном диске для снижения веса и травмобезопасности\n        translate([0, 0, flange_thickness - 2.0])\n            difference() {\n                cylinder(d = flange_outer_d + 2 * eps, h = 2.0 + eps);\n                cylinder(d1 = flange_outer_d, d2 = flange_outer_d - 4.0, h = 2.0 + eps);\n            }\n    }\n}\n\n// --- ВИЗУАЛИЗАЦИЯ ИТОГОВОЙ ДЕТАЛИ ---\ncompression_flange();', 0, 0, 'img_7077_6a83891350ef3.png', '2026-08-17 22:20:03', 1, 4808, 'gen-1787005139-wYmF4HaS9W9IdQv7z6hO', '2026-08-17 22:19:23'),
(7076, 'в работе', 'Простой клип-держатель, который крепится на солнцезащитный козырек, позволяя удобно разместить очки, когда они не используются.', '// ==============================================================================\n// ПАРАМЕТРИЧЕСКИЙ КЛИП-ДЕРЖАТЕЛЬ ДЛЯ ОЧКОВ НА СОЛНЦЕЗАЩИТНЫЙ КОЗЫРЕК АВТОМОБИЛЯ\n// ==============================================================================\n// Оптимизировано для печати на боку без поддержек (высокая прочность на изгиб).\n// ==============================================================================\n\n/* [Качество рендеринга] */\n$fn = 36; // Оптимальное качество для быстрой генерации STL ($fn < 50)\n\n/* [Общие габариты] */\n// Ширина клипсы (высота слоя при печати на боку)\nclip_width = 18.0;\n\n/* [Параметры зажима козырька] */\n// Рабочая длина зажима козырька\nvisor_len = 52.0;\n// Толщина солнцезащитного козырька (базовый зазор)\nvisor_gap = 14.0;\n// Толщина стенки силового зажима\nvisor_wall = 3.0;\n// Усилие преднатяга (сужение лапки внутрь)\nvisor_preload = 2.0;\n\n/* [Параметры фиксатора очков] */\n// Длина кармана для очков\nglasses_len = 26.0;\n// Рабочий зазор под дужку очков\nglasses_gap = 7.5;\n// Толщина пружинящей стенки держателя очков\nglasses_wall = 2.4;\n// Зазор в зоне запирающего выступа\nglasses_lock_gap = 3.8;\n\n/* [Фрикционные элементы] */\n// Количество ребер зацепа за ткань козырька\nrib_count = 4;\n// Высота противоскользящих ребер\nrib_height = 0.7;\n// Радиус скругления кромок профиля\nprofile_fillet = 0.6;\n\n\n// --- МОДУЛИ 2D ПРОФИЛЯ ---\n\n// 1. Профиль зажима на козырек\nmodule visor_clamp_2d() {\n    r_in = visor_gap / 2;\n    r_out = r_in + visor_wall;\n    arc_center_x = visor_wall + r_in;\n    leg_x = arc_center_x + r_in + visor_wall / 2;\n\n    // Верхний U-образный изгиб\n    translate([arc_center_x, visor_len]) {\n        difference() {\n            circle(r = r_out);\n            circle(r = r_in);\n            translate([-r_out - 1, -2 * r_out - 1])\n                square([2 * r_out + 2, 2 * r_out + 1]);\n        }\n    }\n\n    // Внешняя прижимная лапка с преднатягом\n    p1 = [leg_x, visor_len];\n    p2 = [leg_x - visor_preload, visor_len * 0.35];\n    p3 = [leg_x + 5.0, visor_len * 0.35 - 8.0];\n\n    hull() {\n        translate(p1) circle(d = visor_wall);\n        translate(p2) circle(d = visor_wall);\n    }\n    hull() {\n        translate(p2) circle(d = visor_wall);\n        translate(p3) circle(d = visor_wall);\n    }\n\n    // Зубья противоскольжения на внутренней стороне хребта\n    for (i = [1 : rib_count]) {\n        y_pos = visor_len * 0.85 - (i - 1) * (visor_len * 0.55 / rib_count);\n        translate([visor_wall, y_pos])\n            polygon([\n                [0, 0],\n                [rib_height, -1.0],\n                [0, -2.0]\n            ]);\n    }\n}\n\n// 2. Профиль пружинного зажима для очков\nmodule glasses_clamp_2d() {\n    g_rin = glasses_gap / 2;\n    g_rout = g_rin + glasses_wall;\n    g_center_x = -g_rin;\n    arm_x = -glasses_gap - glasses_wall / 2;\n\n    // Нижняя U-образная петля\n    translate([g_center_x, 0]) {\n        difference() {\n            circle(r = g_rout);\n            circle(r = g_rin);\n            translate([-g_rout - 1, 0])\n                square([2 * g_rout + 2, 2 * g_rout + 1]);\n        }\n    }\n\n    // Пружинная лапка с замком и направляющим раструбом\n    gp1 = [arm_x, 0];\n    gp2 = [arm_x, glasses_len * 0.65];\n    gp3 = [-glasses_lock_gap - glasses_wall / 2, glasses_len * 0.82];\n    gp4 = [arm_x - 5.5, glasses_len + 3.0];\n\n    hull() {\n        translate(gp1) circle(d = glasses_wall);\n        translate(gp2) circle(d = glasses_wall);\n    }\n    hull() {\n        translate(gp2) circle(d = glasses_wall);\n        translate(gp3) circle(d = glasses_wall);\n    }\n    hull() {\n        translate(gp3) circle(d = glasses_wall);\n        translate(gp4) circle(d = glasses_wall);\n    }\n}\n\n// 3. Объединенный сглаженный 2D-профиль\nmodule full_profile_2d() {\n    offset(r = profile_fillet) offset(r = -profile_fillet) {\n        // Центральный силовой хребет (общая база)\n        translate([0, 0])\n            square([visor_wall, visor_len]);\n\n        visor_clamp_2d();\n        glasses_clamp_2d();\n    }\n}\n\n\n// --- ФИНАЛЬНАЯ 3D МОДЕЛЬ ---\n\nmodule sun_visor_glasses_clip() {\n    // Выдавливание скругленного профиля\n    linear_extrude(height = clip_width, convexity = 10) {\n        full_profile_2d();\n    }\n}\n\n// Построение готового изделия\nsun_visor_glasses_clip();', 0, 0, 'img_7076_6a8388868ad07.png', '2026-08-17 22:17:42', 1, 4808, 'gen-1787004958-7cVEjaoi0JAmY2uGDl8w', '2026-08-17 22:16:25'),
(7075, 'в работе', 'Замена сломанной ручки ящика. Форма - эргономичная, подходящая для большинства стандартных ящиков. Предусмотреть возможность выбора размера (длина, расстояние между крепежными отверстиями).', '// =====================================================================\n// ПАРАМЕТРИЧЕСКАЯ ЭРГОНОМИЧНАЯ РУЧКА ДЛЯ МЕБЕЛЬНЫХ ЯЩИКОВ\n// =====================================================================\n// Оптимизировано для 3D-печати. Без поддержек при печати на боку.\n// =====================================================================\n\n/* [Основные параметры ручки] */\n// Межосевое расстояние между винтами (стандарты: 64, 96, 128, 160, 192)\nhole_distance = 96;       // [32:4:256]\n\n// Полная глубина вылета ручки от плоскости фасада (мм)\nhandle_depth = 28;        // [20:1:50]\n\n// Ширина хвата (высота профиля по оси Z ящика) (мм)\ngrip_height = 16;         // [10:1:30]\n\n// Толщина хвата в глубину (сечение) (мм)\ngrip_thickness = 10;      // [6:1:20]\n\n// Диаметр опорных ножек у основания (мм)\npost_diameter = 14;       // [10:1:25]\n\n// Вылет ручки по краям за пределы крепежных отверстий (мм)\nend_extension = 12;       // [0:1:40]\n\n/* [Параметры крепежа] */\n// Диаметр отверстия под винт (M4 = 3.8-4.2 мм для свободной посадки / 3.2 мм под нарезку)\nscrew_hole_diameter = 3.6; // [2.5:0.1:5.5]\n\n// Глубина резьбового глухого отверстия (мм)\nscrew_hole_depth = 18;    // [8:1:35]\n\n// Входная фаска отверстия для облегчения попадания винтом (мм)\nscrew_chamfer = 1.0;      // [0:0.2:3]\n\n/* [Качество и сглаживание] */\n// Количество граней окружностей (оптимизировано < 50)\n$fn = 36;\n\n// =====================================================================\n// ВЫЧИСЛЯЕМЫЕ ПЕРЕМЕННЫЕ\n// =====================================================================\ntotal_length = hole_distance + 2 * end_extension;\nr_corner = min(post_diameter / 2, grip_thickness / 2);\n\n// =====================================================================\n// ОСНОВНОЙ РЕНДЕР\n// =====================================================================\ndifference() {\n    // 1. Полнотелое тело эргономичной ручки\n    handle_body();\n\n    // 2. Крепежные отверстия в ножках (снизу)\n    mounting_holes();\n}\n\n// =====================================================================\n// МОДУЛИ ПОСТРОЕНИЯ ГЕОМЕТРИИ\n// =====================================================================\n\n// Элемент сечения перекладины/хвата (скругленный эллипс/капсула)\nmodule grip_profile(w, h) {\n    hull() {\n        translate([0, 0, -(h/2 - w/2)])\n            cylinder(d = w, h = 0.01, center = true);\n        translate([0, 0, (h/2 - w/2)])\n            cylinder(d = w, h = 0.01, center = true);\n    }\n}\n\n// Основание опорной ножки с фаской к фасаду\nmodule post_base() {\n    hull() {\n        cylinder(d = post_diameter, h = 1, center = false);\n        translate([0, 0, 4])\n            cylinder(d = post_diameter - 1, h = 0.01, center = false);\n    }\n}\n\n// Модуль основного тела ручки\nmodule handle_body() {\n    half_dist = hole_distance / 2;\n    bridge_y = handle_depth - grip_thickness / 2;\n\n    union() {\n        // --- Центральный мост (основная часть хвата) ---\n        hull() {\n            // Левый узел хвата\n            translate([-half_dist, bridge_y, 0])\n                rotate([90, 0, 0])\n                grip_profile(w = grip_thickness, h = grip_height);\n\n            // Правый узел хвата\n            translate([half_dist, bridge_y, 0])\n                rotate([90, 0, 0])\n                grip_profile(w = grip_thickness, h = grip_height);\n        }\n\n        // --- Декоративные боковые окончания (если end_extension > 0) ---\n        if (end_extension > 0) {\n            // Левое крыло\n            hull() {\n                translate([-half_dist, bridge_y, 0])\n                    rotate([90, 0, 0])\n                    grip_profile(w = grip_thickness, h = grip_height);\n\n                translate([-(half_dist + end_extension), bridge_y - 2, 0])\n                    rotate([90, 0, 0])\n                    scale([0.7, 0.7, 0.7])\n                    grip_profile(w = grip_thickness, h = grip_height);\n            }\n\n            // Правое крыло\n            hull() {\n                translate([half_dist, bridge_y, 0])\n                    rotate([90, 0, 0])\n                    grip_profile(w = grip_thickness, h = grip_height);\n\n                translate([half_dist + end_extension, bridge_y - 2, 0])\n                    rotate([90, 0, 0])\n                    scale([0.7, 0.7, 0.7])\n                    grip_profile(w = grip_thickness, h = grip_height);\n            }\n        }\n\n        // --- Левая эргономичная ножка-стойка ---\n        hull() {\n            // Базовая площадка у фасада\n            translate([-half_dist, 0, 0])\n                rotate([-90, 0, 0])\n                post_base();\n\n            // Переход в верхний узел\n            translate([-half_dist, bridge_y, 0])\n                rotate([90, 0, 0])\n                grip_profile(w = grip_thickness, h = grip_height);\n        }\n\n        // --- Правая эргономичная ножка-стойка ---\n        hull() {\n            // Базовая площадка у фасада\n            translate([half_dist, 0, 0])\n                rotate([-90, 0, 0])\n                post_base();\n\n            // Переход в верхний узел\n            translate([half_dist, bridge_y, 0])\n                rotate([90, 0, 0])\n                grip_profile(w = grip_thickness, h = grip_height);\n        }\n        \n        // Внутренние эргономичные радиусы (плавное скругление под пальцы)\n        fillet_radius = min(post_diameter / 2, (handle_depth - grip_thickness) / 1.5);\n        \n       \n    }\n}\n\n// Модуль выреза отверстий под крепежные винты\nmodule mounting_holes() {\n    half_dist = hole_distance / 2;\n\n    for (x_pos = [-half_dist, half_dist]) {\n        translate([x_pos, -0.01, 0]) {\n            rotate([-90, 0, 0]) {\n                // Основной канал под резьбу винта\n                cylinder(\n                    d = screw_hole_diameter, \n                    h = screw_hole_depth + 0.01, \n                    center = false\n                );\n\n                // Коническая заходная фаска для удобства монтажа\n                if (screw_chamfer > 0) {\n                    cylinder(\n                        d1 = screw_hole_diameter + (screw_chamfer * 2), \n                        d2 = screw_hole_diameter, \n                        h = screw_chamfer, \n                        center = false\n                    );\n                }\n            }\n        }\n    }\n}', 0, 0, 'img_7075_6a8387ce5d934.png', '2026-08-17 22:14:38', 1, 4808, 'gen-1787004702-uUf0plnoUgrehJzEONaM', '2026-08-17 22:12:17');

